using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace NetFrameworkConsoleSketchbook
{
    internal class Program
    {
        static void Main(string[] args)
        {
            EnvDTE.DTE dte = (EnvDTE.DTE)System.Runtime.InteropServices.Marshal.GetActiveObject(&quot;VisualStudio.DTE&quot;);

